+                .andExpect(jsonPath("$.items[0].summary").value("要約テキスト"))
+                .andExpect(jsonPath("$.items[0].author").value("user01"))
+                .andExpect(jsonPath("$.items[0].score").value(10))
+                .andExpect(jsonPath("$.items[0].tags[0]").value("AI"));
