@RequiredArgsConstructor
public class KnowledgeServiceImpl implements KnowledgeService {

    private final NamedParameterJdbcTemplate jdbcTemplate;

    @Override
    @Transactional(readOnly = true)
    public KnowledgePageResponse search(KnowledgeSearchRequest request) {
        MapSqlParameterSource params = new MapSqlParameterSource();

        // ── WHERE 句の構築 ──────────────────────────────────
        StringBuilder where = new StringBuilder(
                "WHERE k.is_deleted = false AND k.status = 'published'"
        );

        // 全文検索：タイトル・本文の部分一致（大文字小文字を無視）
        if (request.getQ() != null && !request.getQ().isBlank()) {
            where.append(" AND (LOWER(k.title) LIKE LOWER(:q) OR LOWER(k.body) LIKE LOWER(:q))");
            params.addValue("q", "%" + request.getQ() + "%");
        }

        // タグフィルタ：指定タグのいずれかを持つ記事のみに絞り込む
        List<String> tagList = parseTags(request.getTags());
        if (!tagList.isEmpty()) {
            where.append(
                    " AND k.id IN (" +
                    "  SELECT kt.knowledge_id FROM knowledge_tag kt" +
                    "  JOIN tag t ON kt.tag_id = t.id" +
                    "  WHERE t.name IN (:tagNames)" +
                    ")"
            );
            params.addValue("tagNames", tagList);
        }

        // ── ORDER BY 句の決定 ────────────────────────────────
        // sort パラメータが明示されている場合は filter より優先する
        String orderBy = resolveOrderBy(request);

        // filter=latest の場合は最大20件に制限
        int effectiveSize = "latest".equals(request.getFilter())
                ? Math.min(request.getSize(), 20)
                : request.getSize();

        // ── 総件数クエリ ──────────────────────────────────────
        String countSql = "SELECT COUNT(DISTINCT k.id) FROM knowledge k " + where;
        Long total = jdbcTemplate.queryForObject(countSql, params, Long.class);
        long totalElements = (total != null) ? total : 0L;

        // ── データ取得クエリ ──────────────────────────────────
        // like_count はコリレートサブクエリで算出（"like" はSQL予約語のため引用符でエスケープ）
        String dataSql =
                "SELECT k.id, k.title, k.body, u.username AS author, k.created_at," +
                " (SELECT COUNT(*) FROM \"like\" l WHERE l.knowledge_id = k.id) AS like_count" +
                " FROM knowledge k" +
                " LEFT JOIN users u ON k.author_id = u.id " +
                where +
                " ORDER BY " + orderBy +
                " LIMIT :size OFFSET :offset";

        params.addValue("size", effectiveSize);
        params.addValue("offset", (long) request.getPage() * effectiveSize);

        List<Map<String, Object>> rows = jdbcTemplate.queryForList(dataSql, params);

        if (rows.isEmpty()) {
            return KnowledgePageResponse.builder()
                    .page(request.getPage())
                    .size(effectiveSize)
                    .totalElements(totalElements)
                    .items(Collections.emptyList())
                    .build();
        }

        // 対象IDを抽出し、タグを一括取得
        List<Long> ids = rows.stream()
                .map(row -> ((Number) row.get("id")).longValue())
                .collect(Collectors.toList());
        Map<Long, List<String>> tagMap = fetchTagsForIds(ids);

        // DTO へのマッピング
        List<KnowledgeItemDto> items = rows.stream()
                .map(row -> {
                    Long id = ((Number) row.get("id")).longValue();
                    return KnowledgeItemDto.builder()
                            .id(id)
                            .title((String) row.get("title"))
                            .summary(buildSummary((String) row.get("body")))
                            .author((String) row.get("author"))
                            .createdAt(DateTimeUtils.toInstant(row.get("created_at")))
                            .score(((Number) row.get("like_count")).longValue())
                            .tags(tagMap.getOrDefault(id, Collections.emptyList()))
                            .build();
                })
                .collect(Collectors.toList());

        return KnowledgePageResponse.builder()
                .page(request.getPage())
                .size(effectiveSize)
                .totalElements(totalElements)
                .items(items)
                .build();
    }

    /**
     * filter / sort パラメータから ORDER BY 句の文字列を決定する。
     * sort が明示されている場合は filter より優先される。
     *
     * @param request 検索リクエスト
     * @return ORDER BY に続く列指定文字列（例: "k.created_at DESC"）
     */
    private String resolveOrderBy(KnowledgeSearchRequest request) {
        if (request.getSort() != null) {
            return switch (request.getSort()) {
                case "created_at" -> "k.created_at ASC";
                case "-created_at" -> "k.created_at DESC";
                case "score" -> "like_count DESC";
                default -> "k.created_at DESC";
            };
        }
        // filter=recommended → いいね数の多い順
        if ("recommended".equals(request.getFilter())) {
            return "like_count DESC";
        }
        // filter=latest またはデフォルト → 作成日時降順
        return "k.created_at DESC";
    }

    /**
     * カンマ区切りのタグ文字列をリストに変換する。
     * 空文字・空白のみのエントリは除外する。
     */
    private List<String> parseTags(String tags) {
        if (tags == null || tags.isBlank()) {
            return Collections.emptyList();
        }
        return Arrays.stream(tags.split(","))
                .map(String::trim)
                .filter(t -> !t.isEmpty())
                .collect(Collectors.toList());
    }

    /**
     * 記事本文の先頭200文字を要約テキストとして返す。
     * 200文字を超える場合は "..." を付加する。
     */
    private String buildSummary(String body) {
        if (body == null || body.isBlank()) {
            return "";
        }
        return body.length() > 200 ? body.substring(0, 200) + "..." : body;
    }

    /**
     * 指定されたknowledge_idリストに対応するタグを一括取得し、
     * knowledge_id → タグ名リスト のマップを返す。
     */
    private Map<Long, List<String>> fetchTagsForIds(List<Long> ids) {
        String tagSql =
                "SELECT kt.knowledge_id, t.name" +
                " FROM knowledge_tag kt" +
                " JOIN tag t ON kt.tag_id = t.id" +
                " WHERE kt.knowledge_id IN (:ids)";
        MapSqlParameterSource tagParams = new MapSqlParameterSource("ids", ids);
        List<Map<String, Object>> tagRows = jdbcTemplate.queryForList(tagSql, tagParams);

        Map<Long, List<String>> tagMap = new HashMap<>();
        for (Map<String, Object> row : tagRows) {
            Long kid = ((Number) row.get("knowledge_id")).longValue();
            String name = (String) row.get("name");
            tagMap.computeIfAbsent(kid, k -> new ArrayList<>()).add(name);
        }
        return tagMap;
    }

}

package com.ginga.naviai.knowledge.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import lombok.Data;

/**
 * 記事検索リクエストパラメータを保持するDTO。
 * GET /api/v1/knowledge のクエリパラメータにバインドされる。
 */
@Data
public class KnowledgeSearchRequest {

    /** 検索語（タイトル・本文の部分一致）。省略可。 */
    private String q;

    /**
     * ソート指定。省略可。
        * 有効値: created_at（投稿日時昇順）| -created_at（投稿日時降順）| score（いいね数降順）
     */
    private String sort;

    /**
     * ビジネスロジックによる絞り込み。省略可。
     * 有効値: recommended（いいね数降順のおすすめ記事）| latest（新着、最大20件）
     */
    private String filter;

    /** ページ番号（0始まり）。省略時はデフォルト0。 */
    @Min(value = 0, message = "pageは0以上を指定してください")
    private int page = 0;

    /** 1ページあたりの件数。省略時はデフォルト20。 */
    @Min(value = 1, message = "sizeは1以上を指定してください")
    @Max(value = 100, message = "sizeは100以下を指定してください")
    private int size = 20;

    /** タグによる絞り込み（カンマ区切り）。省略可。 */
    private String tags;
}

package com.ginga.naviai.knowledge.controller;

import com.ginga.naviai.knowledge.dto.KnowledgePageResponse;
import com.ginga.naviai.knowledge.dto.KnowledgeSearchRequest;
import com.ginga.naviai.knowledge.service.KnowledgeService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 記事検索結果一覧を提供するコントローラ。
 *
 * <p>エンドポイント: {@code GET /api/v1/knowledge}
 *
 * <p>認証は SecurityConfig の {@code anyRequest().authenticated()} ルールにより必須。
 * 期限切れ・不正トークンはJWTフィルタが 401 を返す。
 */
@RestController
@RequestMapping("/api/v1/knowledge")
@RequiredArgsConstructor
public class KnowledgeController {

    private final KnowledgeService knowledgeService;

    /**
     * クエリパラメータを受け取り、条件に合致する記事一覧をページング形式で返す。
     *
     * @param request 検索条件（q, sort, filter, page, size, tags）
     * @return 200: 記事一覧、400: パラメータ不正
     */
    @GetMapping
    public ResponseEntity<KnowledgePageResponse> search(
            @Valid @ModelAttribute KnowledgeSearchRequest request) {
        KnowledgePageResponse response = knowledgeService.search(request);
        return ResponseEntity.ok(response);
    }
}

package com.ginga.naviai.auth.exception;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.BindException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import java.time.format.DateTimeParseException;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.bind.ServletRequestBindingException;
import org.springframework.web.bind.MissingServletRequestParameterException;

import com.ginga.naviai.user.exception.UserNotFoundException;

import java.time.Instant;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.AuthenticationException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@ControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Object> handleValidation(MethodArgumentNotValidException ex, WebRequest request) {
        List<Map<String,String>> errors = new ArrayList<>();
        for (FieldError f : ex.getBindingResult().getFieldErrors()) {
            Map<String,String> err = new HashMap<>();
            err.put("field", f.getField());
            err.put("message", f.getDefaultMessage());
            errors.add(err);
        }
        Map<String,Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.BAD_REQUEST.value());
        body.put("errors", errors);
        return new ResponseEntity<>(body, new HttpHeaders(), HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(BindException.class)
    public ResponseEntity<Object> handleBindException(BindException ex) {
        List<Map<String, String>> errors = new ArrayList<>();
        for (FieldError f : ex.getBindingResult().getFieldErrors()) {
            Map<String, String> err = new HashMap<>();
            err.put("field", f.getField());
            err.put("message", f.getDefaultMessage());
            errors.add(err);
        }
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.BAD_REQUEST.value());
        body.put("errors", errors);
        return new ResponseEntity<>(body, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(DuplicateResourceException.class)
    public ResponseEntity<Object> handleDuplicate(DuplicateResourceException ex) {
        Map<String,Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.CONFLICT.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.CONFLICT);
    }

    @ExceptionHandler(InvalidCredentialsException.class)
    public ResponseEntity<Object> handleInvalidCredentials(InvalidCredentialsException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(AccountNotEnabledException.class)
    public ResponseEntity<Object> handleAccountNotEnabled(AccountNotEnabledException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.FORBIDDEN.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(InvalidTokenException.class)
    public ResponseEntity<Object> handleInvalidToken(InvalidTokenException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(TokenExpiredException.class)
    public ResponseEntity<Object> handleTokenExpired(TokenExpiredException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(UserNotFoundException.class)
    public ResponseEntity<Object> handleUserNotFound(UserNotFoundException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.NOT_FOUND.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler({ServletRequestBindingException.class, MissingServletRequestParameterException.class})
    public ResponseEntity<Object> handleRequestBinding(ServletRequestBindingException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.BAD_REQUEST.value());
        body.put("message", ex.getMessage() == null ? "Bad request" : ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler({MethodArgumentTypeMismatchException.class, DateTimeParseException.class})
    public ResponseEntity<Object> handleTypeMismatch(Exception ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.BAD_REQUEST.value());
        body.put("message", ex.getMessage() == null ? "Bad request" : ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleGeneric(Exception ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.INTERNAL_SERVER_ERROR.value());
        body.put("message", ex.getMessage() == null ? "Internal server error" : ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.INTERNAL_SERVER_ERROR);
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<Object> handleAccessDenied(AccessDeniedException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.FORBIDDEN.value());
        body.put("error", "Forbidden");
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(AuthenticationException.class)
    public ResponseEntity<Object> handleAuthenticationException(AuthenticationException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("error", "Unauthorized");
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }
}

package com.ginga.naviai.mail;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Recover;
import org.springframework.retry.annotation.Retryable;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import java.util.Optional;

@Service
public class SmtpMailService implements MailService {

    private static final Logger logger = LoggerFactory.getLogger(SmtpMailService.class);

    private JavaMailSender mailSender;

    // test helper: allow simulating failures
    private static volatile boolean simulateFailure = false;

    public static void setSimulateFailure(boolean fail) { simulateFailure = fail; }
    public static boolean isSimulateFailure() { return simulateFailure; }

    public SmtpMailService(Optional<JavaMailSender> mailSender) {
        this.mailSender = mailSender.orElse(null);
    }

    // Constructor accepting JavaMailSender directly to support Mockito constructor injection
    public SmtpMailService(JavaMailSender mailSender) {
        this.mailSender = mailSender;
    }

    // No-arg constructor for test frameworks (Mockito @InjectMocks)
    public SmtpMailService() {
        this.mailSender = null;
    }

    @Override
    @Async("mailTaskExecutor")
    @Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(delay = 2000))
    public void send(String to, String subject, String body) {
        if (simulateFailure) {
            throw new RuntimeException("simulated mail failure");
        }
        if (this.mailSender == null) {
            logger.warn("JavaMailSender not configured; skipping send to {}", to);
            return;
        }
        SimpleMailMessage msg = new SimpleMailMessage();
        msg.setTo(to);
        msg.setSubject(subject);
        msg.setText(body);
        mailSender.send(msg);
        logger.info("sent mail to {} subject={}", to, subject);
    }

    @Recover
    public void recover(Exception ex, String to, String subject, String body) {
        logger.error("Failed to send mail to {} after retries: {}", to, ex.getMessage());
        // In production, enqueue for manual retry or save to a failure table for later processing
    }
}

package com.ginga.naviai.auth.filter;

import com.ginga.naviai.auth.service.TokenBlacklistService;
import com.ginga.naviai.auth.util.JwtTokenUtil;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.beans.factory.annotation.Value;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;

import java.io.IOException;

/**
 * JWT 認証フィルタ
 * アクセストークンの jti がブラックリストに登録されていないか検証する
 * 
 * 注意: 現在の実装ではアクセストークンは UUID 形式であり、JWT 形式ではない。
 * 将来 JWT に移行する際は、トークンからクレームを抽出して jti を取得するロジックを追加する。
 * 現時点では、クライアントがリクエストヘッダで jti を渡す設計を想定。
 */
@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private static final Logger logger = LoggerFactory.getLogger(JwtAuthenticationFilter.class);
    private static final String AUTHORIZATION_HEADER = "Authorization";
    private static final String BEARER_PREFIX = "Bearer ";
    private static final String JTI_HEADER = "X-Token-Jti";

    private final TokenBlacklistService tokenBlacklistService;

    @Value("${token.secret}")
    private String tokenSecret;

    @Autowired
    public JwtAuthenticationFilter(TokenBlacklistService tokenBlacklistService) {
        this.tokenBlacklistService = tokenBlacklistService;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, 
                                    HttpServletResponse response, 
                                    FilterChain filterChain) throws ServletException, IOException {
        
        String authHeader = request.getHeader(AUTHORIZATION_HEADER);
        String jti = request.getHeader(JTI_HEADER);
        
        // Authorization ヘッダがない場合はスキップ（認証不要のエンドポイント）
        if (authHeader == null || !authHeader.startsWith(BEARER_PREFIX)) {
            filterChain.doFilter(request, response);
            return;
        }

        String tokenValue = authHeader.substring(BEARER_PREFIX.length()).trim();
        if (tokenValue.isEmpty()) {
            filterChain.doFilter(request, response);
            return;
        }

        try {
            Claims claims = JwtTokenUtil.parseClaims(tokenValue, tokenSecret);
            String jtiFromToken = claims.getId();
            String subject = claims.getSubject();
            String role = claims.get("role", String.class);

            String blacklistJti = (jtiFromToken != null && !jtiFromToken.isEmpty()) ? jtiFromToken : jti;
            if (blacklistJti != null && !blacklistJti.isEmpty()) {
                if (tokenBlacklistService.isBlacklisted(blacklistJti)) {
                    logger.warn("Token with jti {} is blacklisted", blacklistJti);
                    response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                    response.setContentType("application/json");
                    response.getWriter().write("{\"message\":\"Token has been revoked\"}");
                    return;
                }
            }

            if (SecurityContextHolder.getContext().getAuthentication() == null) {
                String authority = (role != null && !role.isBlank()) ? role : "ROLE_USER";
                UsernamePasswordAuthenticationToken authentication =
                    new UsernamePasswordAuthenticationToken(
                        subject,
                        null,
                        java.util.List.of(new SimpleGrantedAuthority(authority))
                    );
                authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                SecurityContextHolder.getContext().setAuthentication(authentication);
            }
        } catch (JwtException ex) {
            logger.warn("Invalid access token", ex);
            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            response.setContentType("application/json");
            response.getWriter().write("{\"message\":\"Invalid access token\"}");
            return;
        }

        filterChain.doFilter(request, response);
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        String path = request.getServletPath();
        // 認証不要のエンドポイントをスキップ
        return path.startsWith("/api/v1/auth/") ||
               path.startsWith("/h2-console");
    }
}

package com.ginga.naviai.auth.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.time.Instant;
import java.util.Date;

public class JwtTokenUtil {

    private static Key getSigningKey(String secret) {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public static String generateAccessToken(String subject, String jti, long expirationSeconds, String secret) {
        return generateAccessToken(subject, jti, expirationSeconds, secret, "ROLE_USER");
        }

        public static String generateAccessToken(String subject, String jti, long expirationSeconds, String secret, String role) {
        Instant now = Instant.now();
        Instant expiresAt = now.plusSeconds(expirationSeconds);

        return Jwts.builder()
            .setSubject(subject)
            .setId(jti)
            .claim("role", role)
            .setIssuedAt(Date.from(now))
            .setExpiration(Date.from(expiresAt))
            .signWith(getSigningKey(secret), SignatureAlgorithm.HS256)
            .compact();
    }

    public static Claims parseClaims(String token, String secret) {
        Jws<Claims> jws = Jwts.parserBuilder()
            .setSigningKey(getSigningKey(secret))
            .build()
            .parseClaimsJws(token);
        return jws.getBody();
    }
}

package com.ginga.naviai.auth.service;

import com.ginga.naviai.auth.dto.RegisterRequest;
import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.auth.dto.LoginRequest;
import com.ginga.naviai.auth.dto.LoginResponse;
import com.ginga.naviai.auth.dto.TokenResponse;
import com.ginga.naviai.auth.exception.AccountNotEnabledException;
import com.ginga.naviai.auth.exception.InvalidCredentialsException;
import com.ginga.naviai.auth.exception.InvalidTokenException;
import com.ginga.naviai.auth.exception.TokenExpiredException;
import java.util.Optional;
import java.util.UUID;

import com.ginga.naviai.auth.entity.User;
import com.ginga.naviai.auth.entity.RefreshToken;
import com.ginga.naviai.auth.exception.DuplicateResourceException;
import com.ginga.naviai.auth.repository.UserRepository;
import com.ginga.naviai.auth.repository.RefreshTokenRepository;
import com.ginga.naviai.auth.repository.ConfirmationTokenRepository;
import com.ginga.naviai.auth.util.TokenUtil;
import com.ginga.naviai.auth.util.JwtTokenUtil;
import com.ginga.naviai.mail.MailService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;

@Service
public class AuthServiceImpl implements AuthService {

    private final UserRepository userRepository;
    private final RefreshTokenRepository refreshTokenRepository;
    private final BCryptPasswordEncoder passwordEncoder;
    private final ConfirmationTokenService tokenService;
    private final MailService mailService;
    private final TokenBlacklistService tokenBlacklistService;

    @Value("${token.secret}")
    private String tokenSecret;

    @Value("${token.access.expiration:3600}")
    private long accessTokenExpiration;

    @Value("${token.refresh.expiration:2592000}")
    private long refreshTokenExpiration;

    @Autowired
    public AuthServiceImpl(UserRepository userRepository,
                           RefreshTokenRepository refreshTokenRepository,
                           BCryptPasswordEncoder passwordEncoder,
                           ConfirmationTokenService tokenService,
                           MailService mailService,
                           TokenBlacklistService tokenBlacklistService) {
        this.userRepository = userRepository;
        this.refreshTokenRepository = refreshTokenRepository;
        this.passwordEncoder = passwordEncoder;
        this.tokenService = tokenService;
        this.mailService = mailService;
        this.tokenBlacklistService = tokenBlacklistService;
    }

    @Override
    public UserResponse register(RegisterRequest request) {
        if (userRepository.findByUsername(request.getUsername()).isPresent()) {
            throw new DuplicateResourceException("username is already taken");
        }
        if (userRepository.findByEmail(request.getEmail()).isPresent()) {
            throw new DuplicateResourceException("email is already registered");
        }

        User u = new User();
        u.setUsername(request.getUsername());
        u.setEmail(request.getEmail());
        u.setPasswordHash(passwordEncoder.encode(request.getPassword()));
        u.setDisplayName(request.getDisplayName());
        u.setEnabled(false);
        u.setCreatedAt(Instant.now());
        u.setUpdatedAt(Instant.now());

        User saved = userRepository.save(u);

        // create confirmation token and send email
        String token = tokenService.createTokenForUser(saved);
        String confirmUrl = String.format("%s/api/v1/auth/confirm?token=%s", "http://localhost:8080", token);
        String subject = "NaviAI - メール確認";
        String body = "登録ありがとうございます。以下のURLからメールを確認してください:\n" + confirmUrl;
        try {
            mailService.send(saved.getEmail(), subject, body);
        } catch (Exception ex) {
            // log and proceed; mail failures should be retried in production
        }

        UserResponse res = new UserResponse();
        res.setId(saved.getId());
        res.setUsername(saved.getUsername());
        res.setEmail(saved.getEmail());
        res.setDisplayName(saved.getDisplayName());
        res.setCreatedAt(saved.getCreatedAt());
        return res;
    }

    @Override
    @Transactional
    public LoginResponse login(LoginRequest request) {
        User user = userRepository.findByUsername(request.getUsernameOrEmail())
                .or(() -> userRepository.findByEmail(request.getUsernameOrEmail()))
                .orElseThrow(() -> new InvalidCredentialsException("Invalid username or password"));

        if (!passwordEncoder.matches(request.getPassword(), user.getPasswordHash())) {
            throw new InvalidCredentialsException("Invalid username or password");
        }

        if (!user.isEnabled()) {
            throw new AccountNotEnabledException("Account is not enabled yet. Please check your email.");
        }

        String accessTokenJti = UUID.randomUUID().toString();
        String accessToken = JwtTokenUtil.generateAccessToken(
            String.valueOf(user.getId()),
            accessTokenJti,
            accessTokenExpiration,
            tokenSecret,
            resolveRole(user)
        );

        // Generate and store refresh token
        String refreshTokenValue = TokenUtil.generateSecureToken();
        String refreshTokenHash = TokenUtil.hashToken(refreshTokenValue, tokenSecret);
        
        Instant expiresAt = Instant.now().plusSeconds(refreshTokenExpiration);
        RefreshToken refreshToken = new RefreshToken(user, refreshTokenHash, expiresAt);
        refreshTokenRepository.save(refreshToken);

        UserResponse userResponse = new UserResponse();
        userResponse.setId(user.getId());
        userResponse.setUsername(user.getUsername());
        userResponse.setEmail(user.getEmail());
        userResponse.setDisplayName(user.getDisplayName());
        userResponse.setCreatedAt(user.getCreatedAt());

        return new LoginResponse(userResponse, accessToken, accessTokenExpiration, refreshTokenValue);
    }

    @Override
    @Transactional
    public TokenResponse refreshTokens(String refreshTokenValue) {
        // Hash the incoming token
        String tokenHash = TokenUtil.hashToken(refreshTokenValue, tokenSecret);

        // Find token in database
        RefreshToken refreshToken = refreshTokenRepository.findByTokenHash(tokenHash)
                .orElseThrow(() -> new InvalidTokenException("Invalid refresh token"));

        // Check if revoked
        if (refreshToken.isRevoked()) {
            throw new InvalidTokenException("Refresh token has been revoked");
        }

        // Check if expired
        if (refreshToken.getExpiresAt().isBefore(Instant.now())) {
            throw new TokenExpiredException("Refresh token has expired");
        }

        User user = refreshToken.getUser();

        // Check if user is still enabled
        if (!user.isEnabled()) {
            throw new AccountNotEnabledException("Account has been disabled");
        }

        // Update last used timestamp
        refreshToken.setLastUsedAt(Instant.now());

        String newAccessTokenJti = UUID.randomUUID().toString();
        String newAccessToken = JwtTokenUtil.generateAccessToken(
            String.valueOf(user.getId()),
            newAccessTokenJti,
            accessTokenExpiration,
            tokenSecret,
            resolveRole(user)
        );

        // Token rotation: generate new refresh token and revoke old one
        String newRefreshTokenValue = TokenUtil.generateSecureToken();
        String newRefreshTokenHash = TokenUtil.hashToken(newRefreshTokenValue, tokenSecret);
        
        Instant newExpiresAt = Instant.now().plusSeconds(refreshTokenExpiration);
        RefreshToken newRefreshToken = new RefreshToken(user, newRefreshTokenHash, newExpiresAt);
        
        // Mark old token as revoked and link to new token
        refreshToken.setRevoked(true);
        refreshToken.setRevokedAt(Instant.now());
        refreshToken.setReplacedBy(newRefreshToken.getJti());
        
        refreshTokenRepository.save(refreshToken);
        refreshTokenRepository.save(newRefreshToken);

        return new TokenResponse(newAccessToken, accessTokenExpiration, newRefreshTokenValue);
    }

    @Override
    @Transactional
    public void logout(String username, Optional<String> refreshTokenValue, Optional<String> accessTokenJti) {
        // リフレッシュトークンが指定されている場合、DB 上で無効化する
        if (refreshTokenValue.isPresent() && !refreshTokenValue.get().isEmpty()) {
            String tokenHash = TokenUtil.hashToken(refreshTokenValue.get(), tokenSecret);
            Optional<RefreshToken> optToken = refreshTokenRepository.findByTokenHash(tokenHash);
            
            if (optToken.isPresent()) {
                RefreshToken refreshToken = optToken.get();
                
                // トークンがリクエストしたユーザーに属しているか確認
                if (!refreshToken.getUser().getUsername().equals(username)) {
                    throw new InvalidTokenException("Token does not belong to the user");
                }
                
                // まだ無効化されていない場合のみ処理
                if (!refreshToken.isRevoked()) {
                    refreshToken.setRevoked(true);
                    refreshToken.setRevokedAt(Instant.now());
                    refreshTokenRepository.save(refreshToken);
                }
            }
            // トークンが存在しない場合は静かに成功扱い（冪等性確保）
        }
        
        // アクセストークンの jti を Redis ブラックリストに追加
        if (accessTokenJti.isPresent() && !accessTokenJti.get().isEmpty()) {
            // TTL はアクセストークンの有効期限（残存時間を正確に計算するには別途対応が必要だが、
            // 簡易実装として全有効期限を使用）
            tokenBlacklistService.addToBlacklist(accessTokenJti.get(), accessTokenExpiration);
        }
    }

    private String resolveRole(User user) {
        if (user == null) {
            return "ROLE_USER";
        }
        boolean isAdmin = "admin".equalsIgnoreCase(user.getUsername())
            || "admin@naviai.com".equalsIgnoreCase(user.getEmail());
        return isAdmin ? "ROLE_ADMIN" : "ROLE_USER";
    }
}

package com.ginga.naviai.user.service;

import com.ginga.naviai.auth.dto.UserResponse;

public interface UserService {
    UserResponse getCurrentUser(Long userId);

    boolean isAdmin(Long userId);
}

package com.ginga.naviai.user.service;

import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.auth.entity.User;
import com.ginga.naviai.auth.repository.UserRepository;
import com.ginga.naviai.user.exception.UserNotFoundException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class UserServiceImpl implements UserService {

    private final UserRepository userRepository;

    @Autowired
    public UserServiceImpl(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @Override
    public UserResponse getCurrentUser(Long userId) {
        User user = userRepository.findById(userId)
            .orElseThrow(() -> new UserNotFoundException("User not found"));

        UserResponse res = new UserResponse();
        res.setId(user.getId());
        res.setUsername(user.getUsername());
        res.setEmail(user.getEmail());
        res.setDisplayName(user.getDisplayName());
        res.setCreatedAt(user.getCreatedAt());
        return res;
    }

    @Override
    public boolean isAdmin(Long userId) {
        return userRepository.findById(userId)
            .map(user -> "admin".equalsIgnoreCase(user.getUsername())
                || "admin@naviai.com".equalsIgnoreCase(user.getEmail()))
            .orElse(false);
    }
}

package com.ginga.naviai.user.controller;

import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.user.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    private final UserService userService;

    @Autowired
    public UserController(UserService userService) {
        this.userService = userService;
    }

    @GetMapping("/me")
    public ResponseEntity<UserResponse> getCurrentUser(Authentication authentication) {
        if (authentication == null || authentication.getName() == null || authentication.getName().trim().isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        Long userId;
        try {
            userId = Long.valueOf(authentication.getName());
        } catch (NumberFormatException ex) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        UserResponse res = userService.getCurrentUser(userId);
        boolean isAdminByAuthority = authentication.getAuthorities().stream()
            .anyMatch(a -> "ROLE_ADMIN".equals(a.getAuthority()));
        boolean isAdmin = isAdminByAuthority || userService.isAdmin(userId);
        res.setAdmin(isAdmin);
        return ResponseEntity.ok(res);
    }
}

package com.ginga.naviai.knowledge.service;

import com.ginga.naviai.knowledge.dto.KnowledgeItemDto;
import com.ginga.naviai.knowledge.dto.KnowledgePageResponse;
import com.ginga.naviai.knowledge.dto.KnowledgeSearchRequest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.namedparam.SqlParameterSource;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/**
 * KnowledgeServiceImpl の単体テスト。
 * NamedParameterJdbcTemplate をモックし、各種検索条件・フィルタ・ソートの動作を検証する。
 */
@ExtendWith(MockitoExtension.class)
class KnowledgeServiceTest {

    @Mock
    private NamedParameterJdbcTemplate jdbcTemplate;

    @InjectMocks
    private KnowledgeServiceImpl service;

    // ── ユーティリティ ─────────────────────────────────────────────

    /** COUNT クエリが 0 を返すようにスタブを設定する。 */
    private void stubCountZero() {
        when(jdbcTemplate.queryForObject(anyString(), any(SqlParameterSource.class), eq(Long.class)))
                .thenReturn(0L);
    }

    /** COUNT クエリが指定件数を返すようにスタブを設定する。 */
    private void stubCount(long count) {
        when(jdbcTemplate.queryForObject(anyString(), any(SqlParameterSource.class), eq(Long.class)))
                .thenReturn(count);
    }

    /** データクエリが空リストを返すようにスタブを設定する。 */
    private void stubEmptyDataRows() {
        when(jdbcTemplate.queryForList(anyString(), any(SqlParameterSource.class)))
                .thenReturn(Collections.emptyList());
    }

    /** 1件分のデータ行を生成する。 */
    private Map<String, Object> buildRow(long id, String title, String body) {
        Map<String, Object> row = new HashMap<>();
        row.put("id", id);
        row.put("title", title);
        row.put("body", body);
        row.put("author", "testuser");
        row.put("created_at", Timestamp.from(Instant.parse("2026-02-01T00:00:00Z")));
        row.put("like_count", 5L);
        return row;
    }

    // ── テスト ─────────────────────────────────────────────────────

    /**
     * 【正常系】パラメータ未指定（デフォルト）で呼び出した場合、
     * 空の結果でも page=0, size=20 を含む正しい構造が返ること。
     */
    @Test
    void search_withDefaultParams_returnsEmptyPage() {
        stubCount(0L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        KnowledgePageResponse result = service.search(req);

        // ページング情報が正しく設定されていること
        assertEquals(0, result.getPage());
        assertEquals(20, result.getSize());
        assertEquals(0L, result.getTotalElements());
        assertTrue(result.getItems().isEmpty());
    }

    /**
     * 【正常系】検索語 q がある場合、クエリパラメータ "q" が
     * NamedParameterJdbcTemplate に渡されること（部分一致形式 %keyword%）。
     */
    @Test
    void search_withQ_addsQParamToQuery() {
        stubCount(1L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setQ("spring");

        service.search(req);

        // COUNT クエリのパラメータを検証
        ArgumentCaptor<SqlParameterSource> paramCaptor = ArgumentCaptor.forClass(SqlParameterSource.class);
        verify(jdbcTemplate).queryForObject(anyString(), paramCaptor.capture(), eq(Long.class));

        SqlParameterSource params = paramCaptor.getValue();
        // "q" パラメータが %spring% 形式で設定されていること
        assertEquals("%spring%", params.getValue("q"));
    }

    /**
     * 【正常系】sort=created_at の場合、データクエリの SQL に
     * "k.created_at ASC" が含まれること。
     */
    @Test
    void search_withSortCreatedAt_usesCreatedAtAscOrder() {
        stubCount(0L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setSort("created_at");

        service.search(req);

        // データクエリの SQL を検証
        ArgumentCaptor<String> sqlCaptor = ArgumentCaptor.forClass(String.class);
        verify(jdbcTemplate).queryForList(sqlCaptor.capture(), any(SqlParameterSource.class));

        // SQL に ORDER BY k.created_at ASC が含まれること（並び順の検証）
        assertTrue(sqlCaptor.getValue().contains("k.created_at ASC"),
            "sort=created_at のとき ORDER BY k.created_at ASC が使われること");
    }

    /**
     * 【正常系】filter=latest の場合、
     * - ORDER BY k.created_at DESC が使われること
     * - size が 20 を超えていても 20 に制限されること。
     */
    @Test
    void search_filterLatest_capsSizeTo20AndUsesCreatedAtOrder() {
        stubCount(0L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setFilter("latest");
        req.setSize(50); // 50 を指定 → 20 に制限されるはず

        KnowledgePageResponse result = service.search(req);

        // size が 20 に制限されていること（filter=latest の最大20件制限）
        assertEquals(20, result.getSize());

        // データクエリが k.created_at DESC を使っていること
        ArgumentCaptor<String> sqlCaptor = ArgumentCaptor.forClass(String.class);
        verify(jdbcTemplate).queryForList(sqlCaptor.capture(), any(SqlParameterSource.class));
        assertTrue(sqlCaptor.getValue().contains("k.created_at DESC"),
                "filter=latest のとき ORDER BY k.created_at DESC が使われること");
    }

    /**
     * 【正常系】filter=recommended の場合、
     * データクエリの SQL に "like_count DESC" が含まれること（いいね数降順）。
     */
    @Test
    void search_filterRecommended_usesLikeCountDescOrder() {
        stubCount(0L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setFilter("recommended");

        service.search(req);

        // データクエリの SQL を検証
        ArgumentCaptor<String> sqlCaptor = ArgumentCaptor.forClass(String.class);
        verify(jdbcTemplate).queryForList(sqlCaptor.capture(), any(SqlParameterSource.class));

        // おすすめ定義：いいね数（like_count）が多い順で返すこと
        assertTrue(sqlCaptor.getValue().contains("like_count DESC"),
                "filter=recommended のとき ORDER BY like_count DESC が使われること");
    }

    /**
     * 【正常系】sort パラメータ（score）は filter より優先されること。
     * filter=recommended かつ sort=score → like_count DESC（変わらないが確認）。
    * filter=recommended かつ sort=created_at → k.created_at ASC に上書きされること。
     */
    @Test
    void search_sortOverridesFilter() {
        stubCount(0L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setFilter("recommended");
        req.setSort("created_at"); // sort が filter を上書きする

        service.search(req);

        ArgumentCaptor<String> sqlCaptor = ArgumentCaptor.forClass(String.class);
        verify(jdbcTemplate).queryForList(sqlCaptor.capture(), any(SqlParameterSource.class));

        // sort=created_at の場合、filter=recommended の like_count DESC より created_at ASC が優先
        assertTrue(sqlCaptor.getValue().contains("k.created_at ASC"),
                "sort パラメータが filter より優先されること");
    }

    /**
     * 【正常系】ページング（page, size）が正しく LIMIT/OFFSET に反映されること。
     */
    @Test
    void search_paginationParametersAreApplied() {
        stubCount(100L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setPage(2);
        req.setSize(10);

        KnowledgePageResponse result = service.search(req);

        // レスポンスに page と size が反映されていること
        assertEquals(2, result.getPage());
        assertEquals(10, result.getSize());
        assertEquals(100L, result.getTotalElements());

        // LIMIT/OFFSET パラメータの検証
        ArgumentCaptor<SqlParameterSource> paramCaptor = ArgumentCaptor.forClass(SqlParameterSource.class);
        verify(jdbcTemplate).queryForList(anyString(), paramCaptor.capture());

        assertEquals(10, paramCaptor.getValue().getValue("size"));
        assertEquals(20L, paramCaptor.getValue().getValue("offset")); // page=2, size=10 → offset=20
    }

    /**
     * 【正常系】タグフィルタ（tags）が指定されている場合、
     * "tagNames" パラメータが設定されること。
     */
    @Test
    void search_withTags_addsTagNamesToParams() {
        stubCount(0L);
        stubEmptyDataRows();

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        req.setTags("AI,設計");

        service.search(req);

        ArgumentCaptor<SqlParameterSource> paramCaptor = ArgumentCaptor.forClass(SqlParameterSource.class);
        verify(jdbcTemplate).queryForObject(anyString(), paramCaptor.capture(), eq(Long.class));

        // tagNames パラメータが設定されていること
        Object tagNamesParam = paramCaptor.getValue().getValue("tagNames");
        assertNotNull(tagNamesParam, "tagNames パラメータが設定されていること");
        List<?> tagNames = (List<?>) tagNamesParam;
        assertEquals(2, tagNames.size());
        assertTrue(tagNames.contains("AI"));
        assertTrue(tagNames.contains("設計"));
    }

    /**
     * 【正常系】データ行が存在する場合、正しくDTOへマッピングされること。
     * - id, title, summary, author, createdAt, score が設定されること
     * - body が200文字を超える場合は先頭200文字＋"..."で切り詰めること
     * - タグ一覧がアイテムに紐付くこと
     */
    @Test
    void search_withDataRows_mapsRowsToDto() {
        stubCount(1L);

        String longBody = "A".repeat(250); // 250文字 → 200文字で切り詰め
        Map<String, Object> row = buildRow(1L, "テスト記事", longBody);

        // 1回目: データクエリ、2回目: タグクエリ
        Map<String, Object> tagRow = new HashMap<>();
        tagRow.put("knowledge_id", 1L);
        tagRow.put("name", "Spring");

        when(jdbcTemplate.queryForList(anyString(), any(SqlParameterSource.class)))
                .thenReturn(List.of(row))   // データクエリ
                .thenReturn(List.of(tagRow)); // タグクエリ

        KnowledgeSearchRequest req = new KnowledgeSearchRequest();
        KnowledgePageResponse result = service.search(req);

        assertEquals(1, result.getItems().size());
        KnowledgeItemDto item = result.getItems().get(0);

        assertEquals(1L, item.getId());
        assertEquals("テスト記事", item.getTitle());
        // 本文が200文字で切り詰められ "..." が付加されること
        assertEquals(200 + 3, item.getSummary().length()); // 200字 + "..."(3字)
        assertTrue(item.getSummary().endsWith("..."));
        assertEquals("testuser", item.getAuthor());
        assertEquals(5L, item.getScore()); // like_count
        assertEquals(List.of("Spring"), item.getTags());
    }
}

package com.ginga.naviai.auth.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.time.Instant;
import java.util.Date;

public class JwtTokenUtil {

    private static Key getSigningKey(String secret) {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public static String generateAccessToken(String subject, String jti, long expirationSeconds, String secret) {
        return generateAccessToken(subject, jti, expirationSeconds, secret, "ROLE_USER");
    }

    public static String generateAccessToken(String subject, String jti, long expirationSeconds, String secret, String role) {
        Instant now = Instant.now();
        Instant expiresAt = now.plusSeconds(expirationSeconds);

        return Jwts.builder()
            .setSubject(subject)
            .setId(jti)
            .claim("role", role)
            .setIssuedAt(Date.from(now))
            .setExpiration(Date.from(expiresAt))
            .signWith(getSigningKey(secret), SignatureAlgorithm.HS256)
            .compact();
    }

    public static Claims parseClaims(String token, String secret) {
        Jws<Claims> jws = Jwts.parserBuilder()
            .setSigningKey(getSigningKey(secret))
            .build()
            .parseClaimsJws(token);
